    output wire         kv_v,
    output reg  [287:0] kv_d,
    output reg          em_v,
    output reg  [257:0] em_d,             // {ue, ce, data}
    output reg          fault
);
    (* keep, ot_rst_split *) reg [1:0] kv_v__qv;   // KV-PC SAFE: 2 kept copies of kv_v
    function kv_v__f; input v; kv_v__f = v; endfunction
