    wire wr_kv = col_v && col_we && !col_sr;      // no KV write data source: a KV WR column is a fault
    wire k_empty = kw == kr;
    wire k_full = (kw[RA-1:0] == kr[RA-1:0]) && (kw[RA] != kr[RA]);
    wire w_empty = ww == wr;
