    (* keep, ot_rst_split *) reg [3:0] ss__qv;   // KV-PC SAFE: 4 kept copies of ss
    function ss__f; input v; ss__f = v; endfunction
    wire ss = ss__qv[0:0];
    (* keep, ot_rst_split *) reg [11:0] bt__qv;   // KV-PC SAFE: 12 kept copies of bt
