            reg hit__nolag;   // KV-PC SAFE clone: hit is a kept copy family (the lag-free MUT 5 is not built)
            always @(*) begin hit__nolag = hit_a; ctx_id = ctx_a; es_expected_valid = x_a; es_expected_identity = eid_a;
